SELECT 'chain' AS k, COUNT(*) AS n, SUM(version_seq IS NULL) AS seqless, SUM(version_seq IS NULL AND changed_at BETWEEN 1792482078 AND 1792482086) AS seqless_rederive, SUM(version_seq IS NULL AND changed_at > 1792482086) AS seqless_after, SUM(version_seq IS NULL AND changed_at < 1792482078) AS seqless_before, MIN(changed_at) AS t0, MAX(changed_at) AS t1 FROM changes WHERE cursor > 958848784 AND cursor <= 958904203 UNION ALL SELECT 'after', COUNT(*), SUM(version_seq IS NULL), NULL, NULL, NULL, MIN(changed_at), MAX(changed_at) FROM changes WHERE cursor > 958904203 AND cursor <= 958914203
